export type HTTPStatusCode1xx = 100 | 101 | 102 | 103;
export type HTTPStatusCode2xx = 200 | 201 | 202 | 203 | 204 | 205 | 206 | 207;
export type HTTPStatusCode3xx = 300 | 301 | 302 | 303 | 304 | 305 | 307 | 308;
export type HTTPStatusCode4xx = 400 | 401 | 402 | 403 | 404 | 405 | 406 | 407 | 408 | 409 | 410 | 411 | 412 | 413 | 414 | 415 | 416 | 417 | 418 | 419 | 420 | 421 | 422 | 423 | 424 | 426 | 428 | 429 | 431 | 451;
export type HTTPStatusCode5xx = 500 | 501 | 502 | 503 | 504 | 505 | 507 | 511;
export type HTTPStatusCodes = HTTPStatusCode1xx | HTTPStatusCode2xx | HTTPStatusCode3xx | HTTPStatusCode4xx | HTTPStatusCode5xx;

export type getStatisticalTableResponse200 = {
  data: TableResponse
  status: 200
}

export type getStatisticalTableResponse404 = {
  data: void
  status: 404
}

export type getStatisticalTableResponse4xx = {
  data: void
  status: Exclude<HTTPStatusCode4xx, 404>
}

export type getStatisticalTableResponse5xx = {
  data: void
  status: HTTPStatusCode5xx
}

export type getStatisticalTableResponseSuccess = (getStatisticalTableResponse200) & {
  headers: Headers;
};
export type getStatisticalTableResponseError = (getStatisticalTableResponse404 | getStatisticalTableResponse4xx | getStatisticalTableResponse5xx) & {
  headers: Headers;
};

export type getStatisticalTableResponse = (getStatisticalTableResponseSuccess | getStatisticalTableResponseError)

export const getGetStatisticalTableUrl = (params: GetStatisticalTableParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `https://www.censtatd.gov.hk/api/get.php?${stringifiedParams}` : `https://www.censtatd.gov.hk/api/get.php`
}

/**
 * Returns the requested C&SD Web Tables in JSON format.
 * @summary Retrieve the statistics for Web Tables
 */
export const getStatisticalTable = async (params: GetStatisticalTableParams, options?: RequestInit, fetchFn?: typeof globalThis.fetch): Promise<getStatisticalTableResponse> => {

  const res = await (fetchFn ?? fetch)(getGetStatisticalTableUrl(params),
  {
    ...options,
    method: 'GET'


  }
)


  const body = [204, 205, 304].includes(res.status) ? null : await res.text();

  const data: getStatisticalTableResponse['data'] = body ? JSON.parse(body) : {}
  return { data, status: res.status, headers: res.headers } as getStatisticalTableResponse
}
